<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,reactive,ref,watch} from 'vue';
import {beijingTime} from '@quote/archive-client';
import {request,mutate,pending} from '../api';
import {FinanceController,createFinanceState,financeBusy,financeDirty,termLabel,exceptionLabel,type FinanceTarget,type ReminderConfiguration} from '../../../../packages/finance-client/src/index';
const props=defineProps<{locked?:boolean;admin?:boolean;initialTarget?:FinanceTarget;reminderConfiguration?:ReminderConfiguration}>();
const emit=defineEmits<{(e:'busy-changed',value:boolean):void;(e:'failure',value:unknown):void}>();
const state=reactive(createFinanceState(!!props.admin)),ack=ref(false),subscribing=ref(false),subscriptionNotice=ref('');
const controller=new FinanceController(request,(label,path,body)=>mutate(label,path,'POST',body),state,e=>emit('failure',e));
const busy=computed(()=>financeBusy(state)||subscribing.value),dirty=computed(()=>financeDirty(state)),locked=computed(()=>!!props.locked||busy.value),writeLocked=computed(()=>locked.value||!!pending.value||!!state.review),navigationLocked=computed(()=>locked.value||dirty.value||!!state.review||!!pending.value),exceptionWritable=computed(()=>!props.admin&&!!state.detail?.receivable.writable&&!!state.exceptions?.writable),termWritable=computed(()=>!props.admin&&!!state.context&&!!state.terms?.writable&&knownTerms.value),knownTerms=computed(()=>state.terms?.originalTermDays!=null&&state.terms?.effectiveTermDays!=null&&!!state.terms?.dueDate),pages=computed(()=>state.page?Math.max(1,Math.ceil(state.page.total/state.page.pageSize)):1),pendingException=computed(()=>state.exceptions?.items.find(e=>e.status==='pending_verification'));
const subscriptionConfigured=computed(()=>!!props.reminderConfiguration?.available&&!!props.reminderConfiguration.templateId);
const picked=(e:unknown)=>Number((e as {detail:{value:string}}).detail.value);
watch(()=>busy.value||dirty.value||!!state.review||!!pending.value,value=>emit('busy-changed',value),{immediate:true,flush:'sync'});watch(()=>state.review,()=>{ack.value=false;});
function guard(work:()=>void){try{state.error='';work();}catch(e){state.error=(e as Error).message;}}
async function safely(work:()=>Promise<void>){try{await work();}catch(e){state.error=(e as Error).message;}}
async function openTarget(target:FinanceTarget){if(locked.value||dirty.value||state.review||pending.value)return;await safely(()=>controller.openTarget(target));}
async function openAfterRecovery(target:FinanceTarget){await controller.openTarget(target,true);state.notice=state.error?'原操作已确认提交；最新事实读取失败，请重新加载。':'原操作已确认提交，已重新读取账期、异常与余额。';}
async function refresh(){if(navigationLocked.value)return;await safely(()=>state.selected?controller.openTarget(state.selected):controller.bootstrap());}
async function commit(){if(locked.value||pending.value||!ack.value)return;try{await controller.commit();}catch{/* error and original pending remain visible */}}
function verification(e:unknown){state.form.verificationResult=picked(e)===1?'continue_collection':'';state.form.resolveId=pendingException.value?.id||'';controller.invalidateReview();}
function subscriptionError(e:unknown){return e instanceof Error?e.message:'订阅申请失败，请稍后重试。';}
async function subscribe(){const templateId=props.reminderConfiguration?.templateId||'';if(navigationLocked.value||!props.reminderConfiguration?.available||!templateId)return;
 // #ifndef MP-WEIXIN
 subscriptionNotice.value='请在真实微信小程序中申请订阅；当前页面没有申请或发送微信提醒。';return;
 // #endif
 // #ifdef MP-WEIXIN
 subscribing.value=true;subscriptionNotice.value='';try{const result=await new Promise<Record<string,string>>((resolve,reject)=>uni.requestSubscribeMessage({tmplIds:[templateId],success:r=>resolve(r as unknown as Record<string,string>),fail:reject}));const decision=result[templateId];if(decision!=='accept'&&decision!=='reject'){subscriptionNotice.value='微信未返回可记录的订阅选择，请重新申请。';return;}await mutate('记录微信订阅选择','/sales/receivable-reminders/subscriptions','POST',{templateId,decision});subscriptionNotice.value=decision==='accept'?'已记录客户端订阅选择；不代表提醒已发送，实际提醒仍需满足微信及业务条件。':'已记录拒绝订阅，站内到期列表仍可查看。';}catch(e){subscriptionNotice.value=subscriptionError(e);emit('failure',e);}finally{subscribing.value=false;}
 // #endif
}
defineExpose({refresh,openTarget,openAfterRecovery,canLeave:()=>!busy.value&&!dirty.value&&!state.review&&!pending.value});
onMounted(async()=>{await controller.bootstrap();if(props.initialTarget)await controller.openTarget(props.initialTarget);});onBeforeUnmount(()=>{controller.dispose();emit('busy-changed',false);});
</script>
<template>
 <view class="finance-workspace">
  <text class="eyebrow">到期跟进与账期管理</text><text class="title">{{state.mode==='hospital'?'医院默认账期':state.mode==='order'?'本单账期与异常':'到期与逾期提醒'}}</text><text class="subtle">异常暂停催收的订单仍可查；本站列表不代表微信提醒已发送。</text>
  <view v-if="pending" class="notice">「{{pending.label}}」结果待核对。原输入和操作标识已保留，请使用页面顶部的核对入口处理。</view><view v-if="state.error" class="error">{{state.error}}</view><view v-if="state.notice" class="notice">{{state.notice}}</view><text v-if="busy" class="empty">正在读取或提交，请稍候…</text>
  <view v-if="dirty||state.review" class="unsaved"><text>有未保存的修改，请复核提交或放弃后再切换。</text><button :disabled="locked||!!pending" @click="controller.discard()">放弃本次修改</button></view>
  <view v-if="state.mode!=='reminders'" class="actions"><button :disabled="navigationLocked" @click="safely(()=>controller.home())">← 返回到期列表</button><button :disabled="navigationLocked" @click="refresh">载入最新事实</button></view>
  <template v-if="state.mode==='reminders'">
   <view class="subscription"><text v-if="!subscriptionConfigured" class="tiny">微信订阅提醒未配置，当前仅可查看站内到期列表。</text><template v-else><text class="tiny">微信订阅选择由真实小程序申请；提醒仍受模板、授权及业务状态限制。</text><button :disabled="navigationLocked" @click="subscribe">申请微信订阅提醒</button></template><text v-if="subscriptionNotice" class="tiny">{{subscriptionNotice}}</text></view>
   <view v-if="state.listError" class="error">{{state.listError}}<button :disabled="locked" @click="controller.reminders()">重新查询</button></view>
   <template v-if="state.page"><view class="result-head"><text>到期 / 逾期未收 {{state.page.total}} 单</text><text class="tiny">金额单位：元</text></view><button v-for="item in state.page.items" :key="item.id" class="order-row" :disabled="navigationLocked" @click="openTarget({orderId:item.orderId,receivableId:item.id})"><view class="row-heading"><text class="hospital">{{item.hospitalName}}</text><text class="tiny">{{item.dueState==='due'?'今日到期':'逾期未收'}} ›</text></view><text class="subtle small">{{item.orderNo}} · 到期 {{item.dueDate}}</text><view class="row-facts"><view><text class="tiny">应收</text><text>{{item.amount}}</text></view><view><text class="tiny">有效已收</text><text>{{item.paid}}</text></view><view><text class="tiny">未收余额</text><text class="amount">{{item.balance}}</text></view></view><text v-if="item.paused" class="pause">异常暂停催收 · 金额与到期日仍保留</text><text class="subtle small">{{item.ownerName}} · {{item.writable&&!admin?'可处理':'只读查阅'}} · 查看账期 / 异常</text></button><text v-if="!state.page.items.length" class="empty">暂无到期未收应收。</text><view class="pagination"><button :disabled="navigationLocked||state.page.page<=1" @click="controller.reminders(state.page.page-1)">上一页</button><text>第 {{state.page.page}} / {{pages}} 页</text><button :disabled="navigationLocked||state.page.page>=pages" @click="controller.reminders(state.page.page+1)">下一页</button></view><text class="tiny">读取于 {{beijingTime(state.page.asOf)}}</text></template>
   <view v-if="!admin" class="section"><text class="section-title">本人负责医院的默认账期</text><text class="subtle small">仅之后新建订单采用新默认值，旧单保持原快照。</text><view v-if="state.hospitalError" class="error">{{state.hospitalError}}<button :disabled="locked" @click="controller.hospitals()">重新读取医院</button></view><button v-for="h in state.hospitals" :key="h.id" class="hospital-link" :disabled="navigationLocked" @click="safely(()=>controller.openHospital(h.id))">{{h.name}} · 维护默认账期 ›</button><text v-if="!state.hospitalsLoading&&!state.hospitals.length" class="tiny">暂无本人负责的医院。</text></view>
   <text class="footnote">自动催收从北京时间每日 09:00 起评估；结清、作废和异常暂停订单不自动催收。</text>
  </template>
  <template v-if="state.mode==='hospital'&&state.hospitalTerm"><view class="section"><text class="section-title">{{state.hospitals.find(h=>h.id===state.hospitalTerm?.hospitalId)?.name}}</text><text class="record-fact">当前默认账期：{{termLabel(state.hospitalTerm.paymentTermDays)}}</text><view class="notice">仅之后新建订单采用新默认值，不改旧单账期、到期日或金额。</view><label class="field"><text>新默认账期 / 自然日</text><input v-model="state.form.hospitalDays" type="number" maxlength="4" :disabled="writeLocked" @input="controller.invalidateReview()" /></label><button class="primary full" :disabled="writeLocked" @click="guard(()=>controller.reviewHospital())">复核默认账期</button></view></template>
  <template v-if="state.mode==='order'&&state.terms&&state.context"><view class="order-heading"><text class="eyebrow">{{state.context.orderNo}}</text><text class="section-title">{{state.context.hospitalName}}</text><text class="subtle small">实际接收 {{state.context.receivedDate}} · {{state.detail?.receivable.owner.name||'负责人见原单'}}{{termWritable||exceptionWritable?'':' · 只读'}}</text></view>
   <view v-if="state.detail" class="row-facts account-facts"><view><text class="tiny">应收 / 元</text><text>{{state.detail.receivable.amount}}</text></view><view><text class="tiny">有效已收 / 元</text><text>{{state.detail.receivable.paid}}</text></view><view><text class="tiny">未收余额 / 元</text><text class="amount">{{state.detail.receivable.balance}}</text></view></view><view v-if="state.exceptions?.paused" class="notice">异常暂停催收，原金额和到期日仍保留。</view><view v-if="!state.detail" class="notice">尚未形成应收。</view><view v-if="!termWritable&&!exceptionWritable" class="notice">本单只读。账期调整、异常登记及解除由当前订单负责销售处理；历史原账期未知时先核实当时约定。</view>
   <view class="section"><text class="section-title">本单账期</text><text class="record-fact">原始账期快照：{{termLabel(state.terms.originalTermDays)}}</text><text class="record-fact">当前生效账期：{{termLabel(state.terms.effectiveTermDays)}}</text><text class="record-fact">当前到期日：{{state.terms.dueDate||'待核实'}}</text><view v-if="!knownTerms" class="notice">历史原账期待核实，不能通过单笔调整绕过核实。</view><template v-if="termWritable"><label class="field"><text>新账期 / 自然日</text><input v-model="state.form.termDays" data-field="term-days" type="number" maxlength="4" :disabled="writeLocked" @input="controller.invalidateReview()" /></label><label class="field"><text>调整原因</text><textarea v-model="state.form.termReason" data-field="term-reason" maxlength="500" :disabled="writeLocked" @input="controller.invalidateReview()"></textarea></label><text class="tiny">从原实际接收日期重新计算到期日；不改金额和医院默认值，不自动解除异常。</text><button class="primary full" :disabled="writeLocked" @click="guard(()=>controller.reviewTerm())">复核账期调整</button></template></view>
   <view class="section"><text class="section-title">取消 / 退款异常</text><text class="subtle small">异常仅暂停催收，保留原金额及结清状态；不执行退款。确需取消或退款时继续线下处理。</text><template v-if="pendingException"><view class="notice">{{exceptionLabel(pendingException.exceptionType)}}待核实 · 异常暂停催收</view><template v-if="exceptionWritable"><label class="field"><text>线下核实结果</text><picker :range="['请选择核实结果','确认仍需正常收款']" :value="state.form.verificationResult?1:0" :disabled="writeLocked" @change="verification"><view class="select">{{state.form.verificationResult?'确认仍需正常收款':'请选择核实结果'}} ⌄</view></picker></label><label class="field"><text>解除原因</text><textarea v-model="state.form.resolveReason" maxlength="500" :disabled="writeLocked" @input="state.form.resolveId=pendingException!.id;controller.invalidateReview()"></textarea></label><button class="full" :disabled="writeLocked" @click="guard(()=>controller.reviewResolve())">复核解除异常</button></template></template><template v-else-if="exceptionWritable"><label class="field"><text>异常类型</text><picker :range="['取消请求','退款请求']" :value="state.form.exceptionType==='refund'?1:0" :disabled="writeLocked" @change="state.form.exceptionType=picked($event)===1?'refund':'cancellation';controller.invalidateReview()"><view class="select">{{exceptionLabel(state.form.exceptionType)}} ⌄</view></picker></label><label class="field"><text>异常原因</text><textarea v-model="state.form.exceptionReason" maxlength="500" :disabled="writeLocked" @input="controller.invalidateReview()"></textarea></label><button class="full" :disabled="writeLocked" @click="guard(()=>controller.reviewException())">复核异常登记</button></template></view>
   <view class="section"><text class="section-title">账期调整留痕</text><text v-if="!state.terms.adjustments.length" class="tiny">暂无调整，原始快照保留。</text><view v-for="a in state.terms.adjustments" :key="a.id" class="history-record"><text class="record-title">{{termLabel(a.beforeTermDays)}} → {{termLabel(a.afterTermDays)}}</text><text class="record-fact">原始账期：{{termLabel(a.originalTermDays)}}</text><text class="record-fact">到期日：{{a.beforeDueDate||'待核实'}} → {{a.afterDueDate||'待核实'}}</text><text class="record-fact">原因：{{a.reason}}</text><text class="tiny">{{a.recordedByName}} · {{beijingTime(a.recordedAt)}}</text></view></view>
   <view class="section"><text class="section-title">异常登记与解除留痕</text><text v-if="!state.exceptions?.items.length" class="tiny">暂无异常记录。</text><view v-for="e in state.exceptions?.items" :key="e.id" class="history-record"><text class="record-title">{{exceptionLabel(e.exceptionType)}} · {{e.status==='pending_verification'?'待核实，暂停催收':'已解除，继续正常收款'}}</text><text class="record-fact">原异常原因：{{e.reason}}</text><text class="tiny">登记人 {{e.recordedByName}} · {{beijingTime(e.recordedAt)}}</text><template v-if="e.status==='resolved'"><text class="record-fact">核实结果：确认仍需正常收款</text><text class="record-fact">解除原因：{{e.resolveReason}}</text><text class="tiny">解除人 {{e.resolvedByName}} · {{beijingTime(e.resolvedAt)}}</text></template></view></view>
  </template>
  <view v-if="state.review" class="overlay"><view class="dialog" role="dialog" aria-modal="true"><text class="eyebrow">提交前复核</text><text class="section-title">{{state.review.title}}</text><view class="review-facts"><view v-for="(fact,i) in state.review.facts" :key="i"><text class="tiny">{{fact[0]}}</text><text>{{fact[1]}}</text></view></view><view class="notice">{{state.review.impact}}</view><checkbox-group @change="ack=($event as any).detail.value.includes('ack')"><label class="ack"><checkbox value="ack" :checked="ack" :disabled="busy" color="#215f46" /><text>已核对当前对象、变更内容和影响，确认按以上事实提交。</text></label></checkbox-group><view class="actions"><button :disabled="busy" @click="controller.invalidateReview()">返回修改</button><button class="primary" :disabled="locked||!!pending||!ack" @click="commit">{{state.working?'正在提交…':'确认操作'}}</button></view></view></view>
 </view>
</template>
<style scoped>
.finance-workspace{width:100%;min-width:0;padding:18px 0 30px;color:#24382f;overflow:hidden}.eyebrow{display:block;font-size:11px;color:#7a897e;margin:4px 0 8px}.title{display:block;font-size:25px;font-weight:600;margin-bottom:12px;line-height:1.35}.subtle{display:block;color:#77877c;font-size:12px;line-height:1.7}.small{font-size:11px}.tiny{display:block;font-size:10px;line-height:1.7;color:#7b8d80}.field{display:block;margin:18px 0}.field>text{display:block;font-size:11px;color:#53685c;margin-bottom:7px}.field input,.select,.field textarea{height:44px;padding:10px;background:#fff;border:1px solid #cfdbd2;border-radius:4px;font-size:13px;line-height:24px;box-sizing:border-box;overflow:hidden;text-overflow:ellipsis;width:100%}.field textarea{height:88px}button{font-size:12px;background:#fff;color:#215f46;border:1px solid #cfdbd2;border-radius:4px;line-height:24px;padding:8px 11px;min-height:44px;margin:0;white-space:normal}button:after{border:0}button[disabled]{opacity:.45}.primary{background:#215f46;color:#fff;border-color:#215f46}.full{width:100%;margin-top:18px}.actions{display:flex;gap:10px;padding:8px 0 18px}.actions button{flex:1}.result-head{display:flex;justify-content:space-between;padding:22px 0 7px;font-size:12px;border-top:1px solid #dfe7e1}.order-row{display:block;text-align:left;width:100%;padding:20px 0;border:0;border-bottom:1px solid #dfe7e1;border-radius:0;font-size:12px}.row-heading{display:flex;justify-content:space-between;gap:12px;margin-bottom:7px}.hospital{font-size:16px;font-weight:550}.row-facts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;padding:16px 0 12px;line-height:1.7;font-variant-numeric:tabular-nums}.row-facts>view>text{display:block}.amount{font-weight:600;color:#215f46}.pagination{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:22px 0 12px;font-size:11px;color:#74877a}.empty{display:block;padding:25px 0;font-size:12px;color:#7a8a7e}.footnote{display:block;font-size:10px;color:#859488;line-height:1.7;margin-top:20px}.error{padding:12px;color:#9b3e32;background:#fbf2ef;font-size:12px;line-height:1.7;white-space:pre-wrap;margin:14px 0}.notice{font-size:11px;line-height:1.7;color:#215f46;background:#eef5f0;padding:12px;margin:14px 0;border-left:2px solid #215f46}.unsaved{font-size:11px;line-height:1.7;color:#68552c;background:#f7f2e8;padding:12px;margin:14px 0}.unsaved button{margin-top:10px}.section{padding-top:25px;margin-top:25px;border-top:1px solid #dfe7e1}.section-title{font-size:17px;font-weight:550;display:block;margin-bottom:10px}.hospital-link{width:100%;margin-top:12px;text-align:left}.order-heading{margin:22px 0 8px}.account-facts{font-size:16px;border-top:1px solid #dfe7e1;border-bottom:1px solid #dfe7e1;margin:20px 0 15px}.record-fact{display:block;font-size:11px;line-height:1.8;margin:9px 0;overflow-wrap:anywhere;white-space:pre-wrap}.record-title{display:block;font-size:13px;font-weight:550;line-height:1.7}.history-record{padding:20px 0;border-bottom:1px solid #e7ece8}.pause{display:block;font-size:11px;line-height:1.7;color:#8a6228;margin:3px 0 8px}.subscription{padding:18px 0}.subscription button{margin-top:12px}.overlay{position:fixed;inset:0;background:#15251b66;display:flex;align-items:flex-end;justify-content:center;z-index:20}.dialog{background:#fff;padding:26px 22px calc(24px + env(safe-area-inset-bottom));width:100%;max-width:600px;box-sizing:border-box;max-height:90vh;overflow-y:auto}.review-facts{display:grid;gap:14px;padding:18px 0;font-size:12px;line-height:1.8;white-space:pre-wrap;overflow-wrap:anywhere}.ack{display:flex;align-items:start;gap:8px;font-size:11px;line-height:1.7;margin:15px 0 22px}.ack checkbox{transform:scale(.8);transform-origin:top left;width:25px;flex-shrink:0}.ack text{flex:1}@media(min-width:700px){.dialog{margin-bottom:8vh}.overlay{align-items:center}}
</style>
